-- The Turning application's code key (ISO toolholders and boring bars) on its
-- Solutions tab, editable there; added unless one exists.
INSERT INTO "AppSetting" ("key", "value")
SELECT 'codekey.app.' || a."id", $ck${"title": "Toolholder identification system (ISO) – Turning", "subtitle": "Toolholders and boring bars", "example": "MWLNR 2525M-08W", "decoder": "iso-turning", "sections": [{"key": "p4", "title": "4 · Clamping system", "sample": "M", "rows": [{"code": "C", "meaning": "Top clamp (Iscadex)"}, {"code": "P", "meaning": "Lever lock"}, {"code": "S", "meaning": "Screw clamping (SC)"}, {"code": "M", "meaning": "Top wedge lock (W / MW at position 12)"}, {"code": "D", "meaning": "Rigid clamp"}]}, {"key": "p5", "title": "5 · Insert shape", "sample": "W", "rows": [{"code": "W", "meaning": "Trigon, 80°"}, {"code": "C", "meaning": "Rhombic, 80°"}, {"code": "T", "meaning": "Triangle, 60°"}, {"code": "R", "meaning": "Round"}, {"code": "L", "meaning": "Rectangular"}, {"code": "V", "meaning": "Rhombic, 35°"}, {"code": "D", "meaning": "Rhombic, 55°"}, {"code": "S", "meaning": "Square, 90°"}, {"code": "K", "meaning": "Parallelogram, 55°"}, {"code": "Q", "meaning": "Special, 80°"}]}, {"key": "p6", "title": "6 · Approach angle", "sample": "L", "rows": [{"code": "A", "meaning": "90°"}, {"code": "B", "meaning": "75°"}, {"code": "D", "meaning": "45°"}, {"code": "E", "meaning": "60°"}, {"code": "F", "meaning": "90°"}, {"code": "G", "meaning": "91°"}, {"code": "J", "meaning": "93°"}, {"code": "K", "meaning": "75°"}, {"code": "L", "meaning": "95°"}, {"code": "N", "meaning": "62.5°"}, {"code": "Q", "meaning": "107.5°"}, {"code": "R", "meaning": "75°"}, {"code": "S", "meaning": "45°"}, {"code": "U", "meaning": "93°"}, {"code": "V", "meaning": "72.5°"}, {"code": "X", "meaning": "Special"}], "note": "Codes with the same angle differ in the tool's geometry — see their pictures."}, {"key": "p7", "title": "7 · Insert clearance angle", "sample": "N", "rows": [{"code": "N", "meaning": "0°"}, {"code": "B", "meaning": "5°"}, {"code": "C", "meaning": "7°"}, {"code": "P", "meaning": "11°"}, {"code": "D", "meaning": "15°"}, {"code": "O", "meaning": "Other"}]}, {"key": "p8", "title": "8 · Hand of tool", "sample": "R", "rows": [{"code": "R", "meaning": "Right"}, {"code": "N", "meaning": "Neutral"}, {"code": "L", "meaning": "Left"}]}, {"key": "p9", "title": "9 · Shank height", "sample": "25", "rows": [{"code": "##", "meaning": "Shank height H in mm (e.g. 25 = 25 mm)"}]}, {"key": "p10", "title": "10 · Shank width", "sample": "25", "rows": [{"code": "##", "meaning": "Shank width b in mm (e.g. 25 = 25 mm)"}]}, {"key": "p3", "title": "3 · Tool length", "sample": "M", "rows": [{"code": "A", "meaning": "32 mm"}, {"code": "B", "meaning": "40 mm"}, {"code": "C", "meaning": "50 mm"}, {"code": "D", "meaning": "60 mm"}, {"code": "E", "meaning": "70 mm"}, {"code": "F", "meaning": "80 mm"}, {"code": "G", "meaning": "90 mm"}, {"code": "H", "meaning": "100 mm"}, {"code": "J", "meaning": "110 mm"}, {"code": "K", "meaning": "125 mm"}, {"code": "L", "meaning": "140 mm"}, {"code": "M", "meaning": "150 mm"}, {"code": "N", "meaning": "160 mm"}, {"code": "P", "meaning": "170 mm"}, {"code": "Q", "meaning": "180 mm"}, {"code": "R", "meaning": "200 mm"}, {"code": "S", "meaning": "250 mm"}, {"code": "T", "meaning": "300 mm"}, {"code": "U", "meaning": "350 mm"}, {"code": "V", "meaning": "400 mm"}, {"code": "W", "meaning": "450 mm"}, {"code": "Y", "meaning": "500 mm"}, {"code": "X", "meaning": "Special"}]}, {"key": "p11", "title": "11 · Insert size", "sample": "08", "rows": [{"code": "##", "meaning": "Cutting edge length in mm (e.g. 08 = 8 mm)"}]}, {"key": "p12", "title": "12 · Wedge lock", "sample": "W", "rows": [{"code": "W", "meaning": "W – Top wedge"}, {"code": "MW", "meaning": "MW – Multi-wedge"}, {"code": "S", "meaning": "For Swiss-type machines"}], "note": "Axial (GAMP) and radial (GAMF) rake angles: see the catalog drawing for toolholders and boring bars."}, {"key": "p1", "title": "1 · Boring bar", "rows": [{"code": "S", "meaning": "Steel shank"}, {"code": "A", "meaning": "Coolant through steel shank"}, {"code": "C", "meaning": "Solid carbide shank"}, {"code": "E", "meaning": "Coolant through carbide shank"}], "note": "Boring bars: S25S MWLNR-08W = positions 1 2 3 · 4–8 · 11 12."}, {"key": "p2", "title": "2 · Bar diameter", "rows": [{"code": "##", "meaning": "Bar diameter d in mm (e.g. 25 = 25 mm)"}]}]}$ck$
FROM "Application" a
WHERE lower(a."name") = 'turning'
ON CONFLICT ("key") DO NOTHING;
